import { test, expect, type Page } from '@playwright/test';

const PRICE = /₪\s?\d[\d,]*/;

async function readStep3Price(page: Page): Promise<string> {
  const title = page.locator('h3').filter({ hasText: '₪' });
  await expect(title).toHaveCount(1);
  await title.scrollIntoViewIfNeeded();
  const text = (await title.textContent()) ?? '';
  const match = text.match(PRICE);
  expect(match, `step-3 title "${text}" must contain ₪<number>`).not.toBeNull();
  return match![0].replace(/\s/g, '');
}

async function switchLanguage(page: Page, current: string, target: string) {
  await page.locator('header button').filter({ hasText: current }).first().click();
  await page.getByRole('button', { name: target, exact: true }).click();
}

test.describe('/organizations — tender price in «איך מפרסמים מכרז?» step 3', () => {
  test('Step 3 shows the tender price as ₪<number>, the same in HE/EN/RU/AR', async ({ page }) => {
    // 1. Open /organizations (Hebrew), read the step-3 title
    await page.goto('/organizations');
    await expect(page.getByRole('heading', { name: 'איך מפרסמים מכרז?' })).toBeVisible();
    const he = await readStep3Price(page);

    // 2. Switch to English, then Russian, then Arabic; read the step-3 title each time
    await switchLanguage(page, 'עברית', 'English');
    await expect(page).toHaveURL(/\/en\/organizations/);
    const en = await readStep3Price(page);

    await switchLanguage(page, 'English', 'Русский');
    await expect(page).toHaveURL(/\/ru\/organizations/);
    const ru = await readStep3Price(page);

    await switchLanguage(page, 'Русский', 'العربية');
    await expect(page).toHaveURL(/\/ar\/organizations/);
    const ar = await readStep3Price(page);

    // Expected: same amount in all languages
    expect([en, ru, ar]).toEqual([he, he, he]);
  });
});
